lines+=['', 'All pairwise progression distances are recorded in spatial_audit.json. These are direct distances, not computed walking-route lengths.', '', '| Spatial relationship | Direct distance |','|---|---:|']
for key,label in [('founder_garage_to_core_direct_m','Founder Garage → Startup core'),('core_to_tech_core_center_direct_m','Startup core → Tech Core center'),('core_to_tech_core_southwest_boundary_direct_m','Startup core → nearest Tech Core boundary'),('core_to_spire_direct_m','Startup core → Spire'),('core_to_flashpoint_direct_m','Startup core → Flashpoint')]:lines.append(f'| {label} | {S[key]:.1f} m |')
lines+=['', f"Startup core is defined at {P['core']}. The existing bent centerline from Garage to the Tech approach is approximately {S['route_length_garage_to_tech_approach_m']:.1f} m, including the bridge; it is distinct from the direct distances above.", '', '## Sightlines and visual review','', '| Established camera | Phase 5 Spire crown samples | Phase 6 samples |','|---|---:|---:|']
